package com.learnagent.memory;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="flashcard_review_logs")public class FlashcardReviewLog{@Id private UUID id;@Column(name="card_id",nullable=false)private UUID cardId;@Column(name="session_id")private UUID sessionId;@Enumerated(EnumType.STRING)@Column(nullable=false)private MemoryRating rating;@Column(name="reviewed_at",nullable=false)private Instant reviewedAt;@Column(name="duration_seconds",nullable=false)private int durationSeconds;@Column(name="due_before",nullable=false)private Instant dueBefore;@Column(name="due_after",nullable=false)private Instant dueAfter;@Column(name="scheduled_days",nullable=false)private int scheduledDays;@Column(name="state_before_json",nullable=false,columnDefinition="text")private String stateBeforeJson;@Column(name="state_after_json",nullable=false,columnDefinition="text")private String stateAfterJson;protected FlashcardReviewLog(){}public FlashcardReviewLog(UUID card,UUID session,MemoryRating rating,Instant reviewed,int duration,Instant before,Instant after,int days,String beforeJson,String afterJson){id=UUID.randomUUID();cardId=card;sessionId=session;this.rating=rating;reviewedAt=reviewed;durationSeconds=duration;dueBefore=before;dueAfter=after;scheduledDays=days;stateBeforeJson=beforeJson;stateAfterJson=afterJson;}public UUID getId(){return id;}public UUID getCardId(){return cardId;}public MemoryRating getRating(){return rating;}public Instant getReviewedAt(){return reviewedAt;}public int getDurationSeconds(){return durationSeconds;}public Instant getDueAfter(){return dueAfter;}public int getScheduledDays(){return scheduledDays;}}
